const MONSTER_LORE={"seedpod_mouse":["種のさやの耳で風の音を聞き分け、草の実を集めて巣穴にためこむ。春になると巣穴のまわりに芽が出る。","耳の種がはじけたら、それは大人になったしるし。"],"lotus_root_sproutling":["浅い池のほとりで日なたぼっこをして育つ。体の穴に雨水をためておき、日照りの日に少しずつ飲む。","頭の葉っぱは、すねると閉じてしまう。"],"silk_leaf_caterpillar":["若葉を食べて絹の糸をはき、葉と糸で自分の服を織る。月の明るい夜にだけ糸をつむぐ。","この糸で作った服は、一生ほつれないという。"],"pinecone_sparrow":["松林に群れで暮らし、松ぼっくりの羽をこすり合わせて仲間と話す。落ちた羽からは小さな松が生える。","朝いちばんに鳴くのは、群れでいちばん勇敢な一羽。"],"sprout_ear_mole":["地中を掘り進みながら、芽の耳で木の根の声を聞く。迷った旅人を地下道で村まで送ることもある。","モグリーフの通ったあとの畑は、よく実る。"],"lantern_moth":["夜の空を灯りをともして飛び、迷子の鳥を巣へ導く。灯りの色は気分で変わる。","灯りが青いときは、少しさびしい気分らしい。"],"thunder_feather_owlet":["雷雲の中で生まれ、羽に小さな雷をためこむ。夜でも昼のように物が見える目を持つ。","くしゃみをすると、まわりの電灯がつく。"],"ancient_forest_stag":["古い森の守り神。歩いたあとには花が咲き、角には小鳥が巣を作る。百年に一度だけ人前に姿を見せる。","この鹿に会えた者は、森に迷わなくなるという。"],"acorn_tail_squirrel":["大きなドングリのしっぽに冬の食べ物をしまって運ぶ。しっぽを忘れて埋めたドングリが森になる。","しっぽの中身を数えるのが毎晩の楽しみ。"],"berry_shell_pillbug":["木いちごの殻をまとい、危ないと丸まって実のふりをする。甘い香りで鳥をだますことも。","丸まったまま坂を転がるのが大好き。"],"bubble_cheek_gecko":["ほっぺの袋に泡をためて、壁を伝って水辺を移動する。泡は虹色に光る。","泡をふくらませすぎて、ときどき浮いてしまう。"],"button_mushroom_beetle":["背中にキノコを育てながら森の落ち葉の下で暮らす。キノコが大きくなると引っ越しをする。","背中のキノコは、食べるとちょっとしょっぱい。"],"candle_wax_slug":["古い礼拝堂の燭台にすみつき、ろうを食べて体に灯をともす。歩いたあとは白いろうの道になる。","雨の日は灯が消えないよう、じっとしている。"],"clay_pebble_chick":["川原の粘土から生まれたひよこ。日に当たるほど体が固く丈夫になる。","雨に濡れると、ちょっとだけ形が変わる。"],"clover_cheek_hamster":["ほっぺにクローバーをためこみ、四つ葉だけは大事に巣に飾る。四つ葉の数が多いほど群れで尊敬される。","ほっぺが四つ葉でいっぱいの日は、幸運の日。"],"cottonseed_puff_moth":["綿毛の羽で風に乗り、遠くの野原へ種を運ぶ。羽ばたくと綿毛がふわりと舞う。","くしゃみ一つで、どこまでも飛ばされていく。"],"crescent_shelled_snail":["三日月の形の殻を持ち、月の満ち欠けで殻の光り方が変わる。満月の夜にだけ歌う。","殻の光で、今夜の月がわかる。"],"dandelion_tail_jerboa":["たんぽぽの綿毛のしっぽで大きく跳ね、草原を飛び回る。跳ねるたびに綿毛が飛ぶ。","しっぽが丸坊主になったら、また生えるまで待つ。"],"dew_antler_fawn":["角に朝露をためて森を歩く小鹿。露を飲ませた草花は一日で大きくなる。","角の露は、母鹿からの贈り物。"],"dewdrop_snail":["しずくの殻に朝露をためこむ。殻ごしに見る景色は少しゆがんで見えるという。","晴れた日は、殻を日除けにして昼寝する。"],"honeydrop_grub":["花の蜜をたっぷりためた丸い体で、土の中で冬を越す。春に甘い香りを残して飛び立つ。","おなかを押すと、ほんのり甘い匂いがする。"],"lily_pad_frog":["スイレンの葉を背負い、池に浮かんで昼寝する。葉の上には小さな虫がよく遊びに来る。","葉っぱをかえるのは、年に一度の大仕事。"],"little_bark_gecko":["木の皮そっくりの肌で、木にくっついて身を隠す。森の木の健康を見守っているという。","見つけられたら、ちょっとくやしそう。"],"little_coal_beetle":["洞窟の石炭をかじり、体の中で小さな火をおこして暖をとる。寒い夜は旅人のそばに来る。","ふーっと息をかけると、背中がぽっと赤くなる。"],"little_flint_crow":["火打ち石の羽を持ち、羽ばたくと火花が散る。洞窟の入口で見張りをするのが仕事。","羽ばたきすぎると、ちょっと焦げくさい。"],"marble_eyed_newt":["大理石のような目で、岩の模様を見分けて水辺の道を覚える。迷うことは決してない。","一度通った道は、絶対に忘れない。"],"okra_tail_quokka":["オクラのしっぽを持つ、いつも笑っているような顔のモンスター。おやつを分けてくれる。","笑顔の理由は、本人にもわからない。"],"paper_leaf_bat":["紙のように薄い葉の翼で、夜の森を音もなく飛ぶ。昼は本のすき間で眠る。","本屋の古い本から、たまに出てくる。"],"pea_pod_goby":["豆のさやにすむ小魚。小川の流れに合わせてさやごと流れていく。","三びき並ぶと、本物の豆そっくり。"],"pearl_plum_longsnout_weevil":["長い鼻で花の奥の蜜を吸う。真珠色の殻は雨をはじき、いつもぴかぴか。","鼻が長いのは、においをかぐのが大好きだから。"],"pebble_back_shrew":["背中に小石を並べて身を守る、小さなトガリネズミ。石の並べ方にこだわりがある。","石を一つ取ると、すぐ並べ直す。"],"pebble_fin_minnow":["小石のようなヒレで川底に身をひそめる。群れで泳ぐと川底が動いて見える。","石だと思って踏むと、ぴちっと逃げる。"],"pebble_stacked_golem_cub":["小石が積み重なって生まれた子どものゴーレム。毎日少しずつ石を足して大きくなる。","いつか城壁になるのが夢。"],"puddle_jelly_blob":["雨上がりの水たまりから生まれるプルプルのモンスター。晴れると小さくなり、雨でまた大きくなる。","雨の日がいちばん元気。"],"pumice_shell_snail":["軽石の殻を持ち、水に浮かんで川を下る。火山のふもとで生まれ、海で暮らす。","殻が軽いので、風の日は飛ばされる。"],"raindrop_duckling":["雨つぶから生まれたアヒルの子。雨の日は空から降ってくるように現れる。","水たまりを見つけると、必ず飛びこむ。"],"reed_basket_mudskipper":["アシで編んだかごを背負い、干潟で貝を集めるトビハゼ。かごの編み方は親から教わる。","かごがいっぱいになると、得意げに跳ねる。"],"reed_wing_finch":["アシの葉の翼で湿地を飛ぶヒワ。アシ笛のような声で鳴く。","この声を聞くと、雨がやむという。"],"ribbon_tailed_tadpole":["リボンのしっぽで優雅に泳ぐオタマジャクシ。大人になってもリボンは残る。","リボンの色で、生まれた池がわかる。"],"sleepy_mandrake":["一日のほとんどを土の中で眠って過ごす。起こされると大声で泣くので、そっとしておこう。","夢の中で、いつも誰かと話している。"],"teacup_hermit":["ティーカップを家にするヤドカリ。気に入ったカップが見つかるまで何度も引っ越す。","お茶の時間になると、カップから顔を出す。"],"thimble_eared_chinchilla":["指ぬきのような耳で、遠くの小さな音まで聞き取る。ふわふわの毛は冬でも暖かい。","内緒話は、この子の前では無理。"],"tiny_fern_seahorse":["シダの葉のようなヒレで、海草の森にまぎれて暮らす。父親がたまごを守る。","しっぽで海草につかまって眠る。"],"tiny_moss_pangolin":["背中のうろこにコケを育て、森の湿った地面で暮らす。丸まるとコケの玉にしか見えない。","コケが育ちすぎると、前が見えなくなる。"],"apricot_fan_alpaca":["あんず色の扇のような毛を持ち、高原で群れを作る。毛を刈ると、とても暖かい毛糸になる。","気に入らない相手には、そっぽを向く。"],"autumn_red_panda":["紅葉の森にすみ、木の上で昼寝をする。秋になると毛色がいっそう赤くなる。","落ち葉の上を転がるのが好き。"],"citrus_scale_skink":["みかんの皮のようなうろこを持つトカゲ。日なたで甘酸っぱい香りを放つ。","近づくと、ほんのりみかんの匂い。"],"copper_shell_toad":["銅の殻を背負ったヒキガエル。雨にあたると殻が緑色にさびる。","鳴き声は、鐘の音に少し似ている。"],"mossy_stone_axolotl":["苔むした石のような体で、清らかな泉の底に暮らす。傷ついてもすぐに治る。","にこにこ顔は、生まれつき。"],"celadon_violet_cyclopean_windchime":["ひとつ目の風鈴のようなモンスター。風が吹くと澄んだ音で仲間を呼ぶ。","音色を聞くと、なぜか涼しくなる。"],"coral_pearl_cuttlefish":["サンゴ色の体で真珠のような光を放つイカ。体の色を変えて気持ちを伝える。","うれしいときは、虹色に光る。"],"jade_fuchsia_creeping_pricklypear":["ヒスイ色のサボテンがはうように広がり、砂漠に花を咲かせる。実は甘くて水分たっぷり。","トゲは、本当は照れかくし。"],"pearl_blue_gillfrill_paddlefish":["へらのような長い口で水中のプランクトンを集める。えらのひだが真珠色に光る。","ゆったり泳ぐ姿は、とても優雅。"],"pearl_cobalt_pouch_pelican":["大きなのどの袋で魚をすくい、仲間に分け与える。袋の中は意外と広い。","袋の中から、ときどき忘れ物が出てくる。"],"pearl_crimson_eyeless_clione":["目のない真紅のクリオネ。冷たい海を流れに乗って漂い、光る翼で踊るように泳ぐ。","天使と呼ばれるけれど、食事中は別。"],"pearl_emerald_giant_isopod":["深い海の底で何年も食べずに生きられる大ダンゴムシ。真珠のような殻を持つ。","何年もじっとしていても、平気。"],"sapphire_crowned_seahorse":["ルリ色の冠を持つタツノオトシゴ。海草の森の王族と呼ばれる。","冠を落とすと、必死に探す。"],"silver_ochre_widemaw_frogmouth":["大きな口を持つ夜の鳥。枝のふりをして昼間はじっと動かない。","夜になると、急におしゃべりになる。"],"spear_kingfisher":["槍のようなくちばしで、水面に一直線に飛びこんで魚をとる。狙った獲物は外さない。","一発必中が、自慢。"],"thunder_reed_crane":["雷雨の日に湿原で舞うツル。羽ばたくと小さな稲妻が走る。","雷を怖がらない、ただ一羽の鳥。"],"kelp_antler_otter":["昆布の角を持つカワウソ。角に貝を引っかけて運ぶ。","お気に入りの石を、いつも一つ持っている。"],"moonflower_ghost":["月下美人の咲く夜にだけ現れる花の幽霊。一晩で消えてしまう。","会えた夜は、いい夢が見られる。"],"magnet_shell_armadillo":["磁石の甲羅を持ち、地下の鉄くずを集めて丸くなる。方位磁石を狂わせる。","くっついた鉄くずを取ってあげると喜ぶ。"],"rose_blade_mantis":["バラの花びらのような刃を持つカマキリ。美しさと鋭さをかねそなえる。","花を傷つける者には容赦しない。"],"quartz_backed_salamander":["水晶の背中を持つサンショウウオ。地底の泉で光を集めて暮らす。","背中の水晶は、一つずつ形がちがう。"],"amber_fossil_spiral_spirit":["琥珀に閉じこめられた古代の貝の精。大昔の海の記憶を語る。","話し出すと、千年分は止まらない。"],"amber_lantern_firefly":["琥珀色の灯りをともすホタル。群れで光ると森が昼のように明るくなる。","灯りの合図で、恋の相手を探す。"],"amber_stag_beetle":["琥珀のように輝くクワガタ。大あごで倒木を軽々と持ち上げる。","力くらべなら、誰にも負けない。"],"amethyst_trumpet_chameleon":["ラッパのような頭で音をあやつるカメレオン。体の色と一緒に音色も変わる。","機嫌のいい日は、ファンファーレが鳴る。"],"artichoke_wolffish":["アーティチョークのようなうろこを持つオオカミウオ。岩場の主として恐れられる。","顔はこわいが、子どもにはやさしい。"],"aurora_harp_seal":["オーロラ色の毛を持つアザラシ。氷の上でハープのような声で歌う。","歌声が届くと、空にオーロラが出る。"],"basalt_wing_bat":["玄武岩の翼を持つコウモリ。火山の洞窟の天井に群れでぶら下がる。","翼が重いので、飛ぶのは少し苦手。"],"bismuth_kingfisher":["ビスマスのような虹色の羽を持つカワセミ。光の角度で色が変わる。","見るたびに色がちがうので、仲間も迷う。"],"bronze_casque_scarlet_cassowary":["青銅のかぶとを持つ深紅のヒクイドリ。足の爪は岩も砕く。","怒らせると、とても速い。"],"buckwheat_capybara":["そばの実が大好きなカピバラ。温泉につかってのんびり過ごす。","どんな相手とも、すぐ仲良くなる。"],"burgundy_holly_rootleg_shrub":["ヒイラギの葉と根の足を持つ低木のモンスター。冬になると赤い実をつける。","根っこで歩くので、足あとが土の模様になる。"],"cacao_pod_mantis":["カカオの実にそっくりなカマキリ。甘い香りで虫をおびき寄せる。","触るとほんのりチョコの香り。"],"charcoal_ivory_copperbill_tuftedpuffin":["銅色のくちばしと飾り羽を持つエトピリカ。崖の巣穴で暮らす。","飾り羽の手入れに、一日の半分を使う。"],"chestnut_emerald_burr_rootwalker":["イガグリの体に根の足を持つ。秋の森を歩き回って栗を配る。","イガは痛いが、中身はとてもやさしい。"],"cobalt_glass_whirlpool_spirit":["青いガラスの渦から生まれた精霊。水の流れを自在にあやつる。","くるくる回っていないと落ち着かない。"],"cobalt_ivory_eleveneye_crownscallop":["十一の目で海の中を見張るホタテ。冠のような殻は王族のあかし。","どの目で見ているかは、本人しか知らない。"],"compass_nose_fox":["方位磁石の鼻を持つキツネ。どんな迷路でも必ず出口を見つける。","迷子の道案内は、おまかせ。"],"copper_fan_giant_anteater":["銅色の扇のようなしっぽを持つオオアリクイ。長い舌でアリの巣を掃除する。","しっぽを広げると、まるで日傘。"],"copper_mane_amethyst_numbat":["銅色のたてがみとアメジストの模様を持つフクロアリクイ。夕暮れにだけ姿を見せる。","模様の数は、年の数と同じ。"],"copper_sorrel_secretarybird":["長い脚で草原を歩き、ヘビを踏んで退治するヘビクイワシ。頭の羽ペンが自慢。","羽ペンで、何かを書いているらしい。"],"coral_ivory_eyeless_rafflesia":["サンゴ色の巨大な花のモンスター。強い香りで虫を集める。","香りは、遠くの島まで届く。"],"cork_bud_caiman":["コルクの皮を持つワニ。水に浮かんで昼寝をし、つぼみのような鼻で息をする。","浮かびすぎて、たまに流される。"],"dusk_mushroom_bat":["夕暮れに羽ばたくキノコのコウモリ。胞子を夜空にまいて森を広げる。","胞子が光る夜は、森がよく育つ。"],"emerald_copper_fantail_capercaillie":["エメラルドの扇羽を持つライチョウ。春になると羽を広げて踊る。","踊りの上手さで、群れの長が決まる。"],"emerald_ivory_bladeleg_waterstrider":["刃のような脚で水面をすべるアメンボ。水面に描く模様は芸術品。","一度も沈んだことがないのが自慢。"],"floating_ink_cloud_squid":["墨の雲を浮かべて空を泳ぐイカ。墨で空に絵を描く。","雲の形が変なときは、たぶんこの子のしわざ。"],"frost_petal_moth":["霜の花びらの羽を持つ蛾。冬の朝、窓に霜の模様を描いて回る。","窓の模様は、この子からの手紙。"],"geode_puffin":["晶洞のような模様のくちばしを持つツノメドリ。光る石を集めて巣を飾る。","巣の中は、ちょっとした宝石箱。"],"hourglass_shell_hermit":["砂時計の殻を持つヤドカリ。殻の砂が落ちきると、ひっくり返して時を数える。","待ち合わせには、絶対遅れない。"],"indigo_silver_mane_okapi":["藍色と銀のたてがみを持つオカピ。森の奥の泉を守っている。","しま模様は、森の影にとけこむため。"],"indigo_turquoise_ivorycasque_guineafowl":["象牙のかぶとを持つホロホロチョウ。群れでにぎやかに鳴き交わす。","おしゃべりが止まらない。"],"ivory_chestnut_fourwattle_bellbird":["四本の肉ひげを持つスズドリ。森中に響く鐘のような声で鳴く。","声が大きすぎて、本人も驚く。"],"ivory_coral_spiral_nautilus":["サンゴ色のうずまき殻を持つオウムガイ。殻の部屋に空気をためて浮き沈みする。","大昔から、ずっとこの姿。"],"ivory_rose_bladecrest_cockatoo":["バラ色の刃のようなとさかを持つオウム。人の言葉をまねるのが得意。","教えた言葉は、ちゃんと覚えている。"],"ivory_turquoise_fanplate_slipperlobster":["うちわのような甲羅を持つセミエビ。岩のすき間で静かに暮らす。","うちわであおぐのが、ひそかな特技。"],"jade_copper_latticewing_lacebug":["格子模様の羽を持つグンバイムシ。羽の模様はひとつとして同じものがない。","羽の模様を自慢しに来る。"],"jade_trumpet_lantern_cicada":["ラッパのような口で夏中鳴き続けるセミ。鳴き声で灯りがともる。","夏が終わると、静かに眠る。"],"lantern_anglerfish":["頭のちょうちんで深海を照らすアンコウ。迷った魚を光で導く。","ちょうちんの光は、遠くからでも見える。"],"lantern_seed_crab":["光る種を甲羅に乗せたカニ。種を砂浜に植えて夜の浜辺を照らす。","植えた種は、灯台の花になる。"],"lotus_backed_tapir":["背中にハスの花を咲かせるバク。悪い夢を食べ、きれいな花に変える。","花が大きいほど、たくさん夢を食べた証拠。"],"malachite_cassowary":["クジャク石の羽を持つヒクイドリ。羽の模様は光で波打つ。","走ると、羽が緑の炎のように見える。"],"mercury_spring_blob":["水銀の泉から生まれた銀色のプルプル。どんな形にもなれる。","鏡のふりをするのが得意。"],"midnight_silk_sundisk_spirit":["夜の絹と太陽の円盤から生まれた精霊。夜空に太陽の光を少しだけ残す。","真夜中でも、ほんのり暖かい。"],"moonblade_hare":["三日月の刃のような耳を持つウサギ。月夜の草原を風のように駆ける。","耳で、草を刈ってくれる。"],"moonlit_owl":["月光をまとうフクロウ。夜の森のすべてを見通すという。","知りたいことは、この子に聞くといい。"],"moss_gear_beetle":["苔むした歯車の体を持つ甲虫。歩くたびにカチカチと音がする。","古い時計台の中で生まれたらしい。"],"navy_copper_clawwing_hoatzin":["翼に爪を持つ鳥。ひなのころは爪で木に登る。","においがちょっと独特。"],"oxblood_ivory_capeweb_vampiresquid":["マントのような膜を持つコウモリダコ。深海でマントを広げて身を守る。","マントの裏は、きらきら光る。"],"plum_ivory_amberwhip_vinegaroon":["琥珀のむちを持つサソリモドキ。危ないと酸っぱい霧をふく。","酸っぱい霧は、実はお酢の香り。"],"porcelain_ribbon_cuttlefish":["陶器のような肌とリボンのヒレを持つイカ。静かな入り江を優雅に泳ぐ。","割れものではないので、ご安心を。"],"pumice_pufferfish":["軽石の体を持つフグ。ふくらむと水面にぷかぷか浮かぶ。","ふくらみすぎると、しばらく沈めない。"],"rainbell_heron":["雨の鈴のような声で鳴くサギ。雨の日、池のほとりで静かに魚を待つ。","鳴き声が聞こえたら、もうすぐ雨。"],"rose_quartz_comb_jelly":["ローズクォーツのようなクシクラゲ。光の帯が体を流れるように走る。","光の帯は、虹のエスカレーター。"],"salt_crystal_moray":["塩の結晶でできたウツボ。地底の塩湖の岩穴にすむ。","しょっぱい顔をしているが、性格はおだやか。"],"scarlet_ivory_armored_ibis":["よろいのような羽を持つトキ。沼地の番兵として知られる。","曲がったくちばしで、泥の中の宝物を探す。"],"shale_wing_swallow":["頁岩の翼を持つツバメ。崖の巣に石を積み重ねて家を作る。","帰ってくるときは、必ず同じ巣。"],"silver_bill_violet_shoebill":["銀のくちばしと紫の羽を持つハシビロコウ。何時間でも動かずに獲物を待つ。","動かない記録は、まだ破られていない。"],"silver_crimson_splitplume_moth":["裂けた羽毛のような羽を持つ蛾。羽ばたくと銀と紅の粉が舞う。","粉がかかると、くしゃみが出る。"],"slate_amber_longfinger_ayeaye":["長い指で木の中の虫を探すアイアイ。琥珀の目で闇を見通す。","指で、木の中の音を聞いている。"],"slate_skate":["石板のような平たい体のエイ。海底の砂にもぐって身を隠す。","踏まれても、平気な顔。"],"soot_tail_ferret":["すすのしっぽを持つフェレット。煙突の中を通って家々を回る。","顔がすすで真っ黒なのは、仕事熱心な証拠。"],"tamarind_cricket":["タマリンドの実の羽を持つコオロギ。砂漠の夜に甘酸っぱい音色で鳴く。","鳴き声を聞くと、なぜか喉がかわく。"],"terracotta_rune_pangolin":["テラコッタのうろこにルーン文字が刻まれたセンザンコウ。遺跡の番人の末裔。","うろこの文字は、まだ誰も読めない。"],"thorn_orchid_mantis":["トゲのある蘭そっくりのカマキリ。花にまぎれて獲物を待つ。","本物の花より、ちょっとだけきれい。"],"turquoise_eyeless_radial_orchid":["放射状に花びらを広げる目のない蘭。遺跡の壁に根を張って咲く。","花の中心で、古い歌を口ずさむ。"],"vine_spined_iguana":["背中にツルのトゲを持つイグアナ。ツルを伸ばして木から木へ移る。","ツルが絡まって、ときどき動けなくなる。"],"wind_chime_jellyfish":["風鈴のようなクラゲ。海風に揺れて、澄んだ音を響かせる。","波打ちぎわで、夏の音を鳴らす。"],"ivory_jade_seedcrown_dandelion":["種の冠を持つ大きなたんぽぽの精。冠の種を風に乗せて仲間を増やす。","冠がなくなると、ちょっとさびしそう。"],"ivory_ruby_lanternbelly_firefly":["ルビーのおなかで光るホタル。赤い光は遠くの仲間への合図。","光が強いほど、元気なしるし。"],"mist_glass_dragonfly":["霧のガラスの羽を持つトンボ。朝霧の中でしか姿が見えない。","霧が晴れると、どこにいるかわからない。"],"pearl_frost_hammer_wyrm":["真珠色の霜のハンマーの頭を持つ竜。氷の洞窟の壁をたたいて削る。","たたいた氷は、氷像のように美しい。"],"tempest_peacock_basilisk":["嵐の羽を広げるクジャクのバジリスク。羽を広げると大風が吹く。","羽を見せびらかすと、だいたい天気が荒れる。"],"violet_glassfrill_gecko_dragon":["紫のガラスのえりを持つヤモリの竜。えりを広げて光を集め、熱線をはく。","えりが割れないよう、いつも慎重。"],"celestial_jellyfish":["星空を漂うクラゲ。体の中に小さな星を抱いている。","流れ星は、この子が落とした星らしい。"],"ivory_crescent_shouldereye_dreambeast":["肩に三日月の目を持つ夢の獣。眠る者の夢をのぞいて旅をする。","いい夢は、こっそり分けてもらっている。"],"rhodonite_protea_prowler":["バラ輝石とプロテアの花をまとう豹。花の香りで獲物を惑わす。","足音を立てずに、花畑を歩く。"],"amber_ivory_jawshield_antlion":["盾のような大あごを持つアリジゴク。砂漠の巣穴で何十年も暮らす。","巣穴に落ちたら、まず謝ろう。"],"amber_jade_fanwing_scorpionfly":["扇の翼とサソリの尾を持つシリアゲムシ。翼で風を起こして飛ぶ。","しっぽは見せかけで、刺さない。"],"amber_slate_ribwing_ankylodragon":["あばら骨の翼とよろいの体を持つ竜。しっぽのこぶで岩を砕く。","飛ぶより、歩くほうが好き。"],"basalt_sixleg_hooktail_dragon":["六本の脚と鉤のしっぽを持つ玄武岩の竜。火山の斜面を登って暮らす。","六本脚なので、転んだことがない。"],"brass_throat_frill_dragon":["真鍮のえりを持つ竜。えりを震わせてラッパのような声を出す。","声だけで、敵が逃げていく。"],"bronze_plum_hammerhead_dragon":["ハンマーの頭を持つ青銅と紫の竜。頭突きで山に洞窟を作る。","頭が固いのは、体も心も。"],"burgundy_ivory_sapphireplate_okapi":["サファイアのよろいをまとうオカピ。王家の乗り物として大切にされた。","よろいは重いが、気品は軽やか。"],"clockwork_seed_golem":["ゼンマイ仕掛けの種から育ったゴーレム。毎朝ネジを巻くと一日働く。","ネジを巻き忘れると、昼寝してしまう。"],"cobalt_horn_goat_chimera":["コバルトの角を持つヤギのキメラ。三つの頭で同時に違うことを考える。","三つの頭は、たまにけんかする。"],"copper_emerald_antler_wyvern":["エメラルドの角を持つワイバーン。森の上空を巡回して縄張りを守る。","角に、鳥の巣があることも。"],"copper_feather_condor":["銅の羽を持つコンドル。山頂の上昇気流に乗って何日も飛び続ける。","翼を広げると、小さな雲くらいある。"],"copper_root_boar":["銅の根っこのような牙を持つイノシシ。森を掘り返して道を作る。","突進したら、止まるのは苦手。"],"copper_shovel_jaw_basilisk":["シャベルのあごを持つバジリスク。地下を掘り進んで鉱脈を探す。","見つけた鉱石は、こっそり集めている。"],"copper_shovelplate_sixleg_dragon":["スコップの甲羅と六本脚を持つ竜。地底を掘って巨大な巣を作る。","掘った土で、山ができたことがある。"],"crimson_hooksail_salamander_dragon":["鉤の帆を持つ紅のサラマンダー。溶岩の川を帆を張って泳ぐ。","溶岩の流れには、だれよりもくわしい。"],"crimson_marrow_chimera":["紅の体を持つキメラ。いくつもの生き物の力を宿す。","好き嫌いは、頭によってちがう。"],"crimson_sapphire_armored_lyrebird":["紅とサファイアのよろいをまとうコトドリ。聞いた音をすべてまねできる。","剣の音まで、そっくりにまねる。"],"crimson_twinfan_anchor_dragon":["二枚の扇と錨のしっぽを持つ竜。荒波の海に錨を下ろして眠る。","嵐の夜も、決して流されない。"],"crystal_horned_bison":["水晶の角を持つバイソン。地底の草原を群れで駆ける。","角が光ると、群れが集まる。"],"eclipse_six_wing_roc":["六枚の翼を持つ巨大な鳥。翼を広げると日食のように空が暗くなる。","この鳥が飛ぶと、昼でも星が見える。"],"ember_cockatrice":["燃える羽を持つコカトリス。朝日とともに炎の声で鳴く。","目が合っても、石にはならない。たぶん。"],"ember_fin_koi":["炎のヒレを持つ鯉。火山の湖を泳ぎ、滝をのぼると竜になるという。","滝のぼりの練習を、毎日欠かさない。"],"emerald_broadbeak_feather_wyrm":["広いくちばしと羽毛を持つ竜。森の木の実を食べて暮らす。","竜なのに、木の実が大好物。"],"emerald_shovelhorn_sail_dragon":["シャベルの角と帆の背びれを持つ竜。帆で風を受けて草原を走る。","風がない日は、のんびり歩く。"],"garnet_quill_condor":["ザクロ石の羽ペンを持つコンドル。山の岩に古い文字を刻む。","岩の文字は、この鳥の日記。"],"glacier_manta":["氷河の体を持つマンタ。空を泳ぐように雪原の上を飛ぶ。","通ったあとに、雪が降る。"],"golden_storm_kirin":["黄金の嵐をまとうキリン。現れると雷鳴とともに豊作を告げる。","姿を見た年は、作物がよく実る。"],"ice_tail_snow_leopard":["氷のしっぽを持つユキヒョウ。雪山の頂を音もなく歩く。","しっぽに触ると、手がしびれるほど冷たい。"],"ivory_crimson_crownfin_lionfish":["冠のヒレを持つミノカサゴ。ヒレを広げてサンゴ礁を舞う。","毒のトゲは、身を守るためだけ。"],"ivory_mask_ruby_dreambeast":["ルビーの仮面をつけた夢の獣。仮面の下の顔は誰も見たことがない。","仮面は、夢の中でだけ外すらしい。"],"ivory_ruby_hugebeak_toucan":["ルビー色の大きなくちばしを持つオオハシ。くちばしで果物を割って食べる。","くちばしは、見た目より軽い。"],"jade_crescent_snapping_dragon":["三日月のあごを持つヒスイの竜。かみつく力は竜の中でも一番。","かまれたら、まず離してもらえない。"],"jade_tonghorn_coralplate_dragon":["サンゴのよろいとトングの角を持つ竜。浅瀬のサンゴ礁を守る。","サンゴを荒らす者には、容赦しない。"],"lapis_vault_gargoyle":["ラピスラズリの体を持つガーゴイル。古い宝物庫の門を千年守り続ける。","夜になると、そっと伸びをする。"],"mirror_mask_sphinx":["鏡の仮面を持つスフィンクス。なぞなぞに答えられない者を通さない。","なぞなぞの答えは、いつも言葉。"],"mushroom_armored_bear":["キノコのよろいをまとうクマ。森の奥で冬眠し、春にキノコを配る。","よろいのキノコは、季節で変わる。"],"obsidian_ringback_sixleg_dragon":["黒曜石の輪を背負う六本脚の竜。輪で太陽の熱を集めて吐き出す。","背中の輪は、触るととても熱い。"],"obsidian_tortoise":["黒曜石の甲羅を持つカメ。千年生きて、火山の歴史を見てきた。","話すのはゆっくりだが、言うことは重い。"],"ochre_crescent_frill_hexadrake":["三日月のえりを持つ六本脚の竜。砂丘を六本脚で泳ぐように進む。","えりを広げると、日傘になる。"],"pitcher_plant_dragon":["ウツボカズラの体を持つ竜。甘い香りで獲物を誘い、つぼに閉じこめる。","つぼの中は、ちょっと良い香り。"],"plum_copper_leafy_seadragon":["葉のようなヒレを持つリーフィーシードラゴン。海草の森でゆらゆら漂う。","ゆれる姿は、ほとんど海草。"],"pomegranate_hydra_tree":["ザクロの実のような頭をいくつも持つヒドラの木。実が熟すと新しい頭が生える。","頭の数は、毎年少しずつ増える。"],"abyssal_cathedral_leviathan":["深淵の大聖堂のような背を持つ巨大な海竜。背中には古い鐘が眠る。","鐘が鳴るとき、海の底が目を覚ます。"],"amber_horn_saiga_patriarch":["琥珀の角を持つサイガの長。草原の群れを何代にもわたって導いてきた。","群れの道は、すべてこの角が覚えている。"],"amethyst_mane_tapir_devourer":["アメジストのたてがみを持つ夢喰いのバク。悪夢を食べ尽くし、夜に静けさをもたらす。","満腹の夜は、世界中がぐっすり眠る。"],"bronze_quill_echidna_titan":["青銅の針を持つハリモグラの巨人。地脈を掘り当て、大地の力を眠らせている。","針一本で、山が揺れるという。"],"charcoal_crown_warg_archfiend":["墨色の冠を戴く魔狼の王。夜の森を支配し、遠吠えで嵐を呼ぶ。","主と認めた者には、誰よりも忠実。"],"cobalt_tusk_behemoth":["コバルトの牙を持つベヒーモス。歩くだけで大地が鳴り響く。","眠っているときは、ただの小山。"],"crimson_fan_fourarm_oracle":["紅の扇を四本の腕で操る巫女。扇の風で未来を占う。","占いは、だいたい当たる。だいたい。"],"crimson_sail_gharial_archon":["紅の帆を持つガビアルの王。大河の流れをすべて治める。","川の水が澄んでいるのは、この王のおかげ。"],"garnet_mane_mandrill_patriarch":["ザクロ石のたてがみを持つマンドリルの長。顔の色で群れに号令をかける。","顔が赤くなるほど、本気の合図。"],"golden_lotus_root_archon":["黄金のハスの根から生まれた王。池の底から国の水をきよめる。","ハスプルたちの遠い祖先といわれる。"],"indigo_seveneye_tentacle_oracle":["七つの目と触手を持つ予言者。七つの未来を同時に見る。","どの未来を選ぶかは、見る者しだい。"],"ivory_jade_crane_sovereign":["ヒスイの羽を持つツルの王。千年に一度、空を舞って平和を告げる。","舞いを見た国には、争いが起きない。"],"ivory_rook_citadel_colossus":["城塞そのものが歩き出した巨人。体の中に小さな町があるという。","背中の町の人々は、揺れに慣れている。"],"living_meteor_archon":["生きた流星の王。空から落ちてきて、星の言葉を地上に伝えた。","夜空を見上げては、故郷をなつかしむ。"],"midnight_oarfish_regent":["真夜中の海を統べるリュウグウノツカイ。深海の王国の使者。","姿を見せるのは、大切な知らせのときだけ。"],"obsidian_bellyface_antler_oracle":["腹に顔を持つ黒曜石の角の巫女。二つの口で過去と未来を語る。","二つの口は、ときどき言い合いをする。"],"opal_spindle_seraph":["オパールの糸車を持つ天使。運命の糸をつむぎ、旅人の縁を結ぶ。","あなたと仲間の縁も、この糸車から。"],"pearl_veil_astral_sovereign":["真珠のベールをまとう星の王。夜空の星の並びを守っている。","星座が崩れないのは、この王のおかげ。"],"rosewood_musicbox_behemoth":["紫檀のオルゴールの体を持つベヒーモス。歩くたびに古い子守歌が流れる。","子守歌を聞くと、怪物も眠くなる。"],"sandglass_antlion_emperor":["砂時計の体を持つアリジゴクの帝王。砂漠の時の流れを支配する。","この帝王の前では、時間がゆっくり流れる。"],"scarlet_cacao_root_tyrant":["紅のカカオの根を持つ暴君。森の根を操り、大地を揺るがす。","好物は、もちろんチョコレート。"],"silver_coral_coelacanth_sovereign":["銀のサンゴをまとうシーラカンスの王。太古の海から生き続ける。","海の歴史は、すべてこの王の記憶の中。"],"silver_quill_secretary_executioner":["銀の羽ペンを持つ処刑人。悪い言葉を書き記し、二度と使えなくする。","この鳥の前では、言葉に気をつけよう。"],"storm_tusk_mammoth_god":["嵐の牙を持つマンモスの神。氷河を生み、嵐を鎮める古き神。","この神が歩くと、季節が変わる。"],"thorn_throne_tree_demon":["イバラの玉座に座る樹の魔王。森のすべての根とつながっている。","玉座から立ち上がった姿を見た者はいない。"],"obsidian_ivory_threeface_fourarm_spadetail_demonlord":["翡翠色の鱗と象牙の王冠をまとう魔界の覇王。大きな鉤爪で大地を制し、静かな威厳で軍勢を率いる。","王冠の重さは、誓いの重さだ。"],"jade_violet_fiveeye_mouthless_serpent_demonking":["口を持たず、五つの眼の光で仲間と語り合う蛇の王。山ひとつ向こうの小石まで見えるという。","話しかけると、眼の光で返事をくれる。"],"amethyst_ivory_chesteye_frillgill_salamander_demonking":["胸の魔眼で炎の流れを読み、紫の飾り鰓で熱を逃がしながら溶岩の湖に棲む。","魔眼ににらまれると、ろうそくが一斉に灯る。"],"obsidian_ivory_headless_chestface_demonking":["首のない体の胸に顔を宿す守護者。胸の口で古い言葉を語り、聞いた者に道を示す。","帽子はかぶれないのが、ひそかな悩み。"],"indigo_ivory_trunkeye_fourtusk_mammoth_demonlord":["四本の牙と盾のような額で群れを守る、氷原の魔王。鼻先の眼で吹雪の中でも道を見失わない。","足音ひとつで、遠くの雪崩が止まる。"],"obsidian_ivory_fourwing_crescentfan_owl_demon":["四枚の翼を三日月の扇のように広げ、夜の空を音もなく見張る梟。夜明けとともに姿を消す。","夜ふかしの子どもを、そっと見守っている。"],"midnight_ivory_threehead_moutheye_fox_uma":["三つの首がそれぞれ別の夢を語る妖狐。眠る者の枕もとに現れ、夢の続きを話して聞かせる。","三つの話が混ざると、とても不思議な夢になる。"],"charcoal_ivory_blindface_sixantlereye_nightantelope_uma":["顔に眼がなく、角に宿る六つの眼で暗い森を見通す夜の羚羊。迷い人を森の外まで導く。","角の眼は、まばたきを順番にする。"],"indigo_amber_eyewing_mothman":["眼の模様の大きな翼で夜霧を払う蛾人。霧の夜、灯台の明かりの近くに現れる。","翼の眼ににらまれると、霧が晴れる。"],"ivory_tripod_moonmirror_uma":["月を映す輪を背負い、三本の脚でゆっくり歩く獣。輪に映る月の形で暦を知らせる。","満月の夜は、輪がまぶしいほど光る。"],"sage_ivory_twinhead_winewing_twoleg_wyvern":["二つの頭で前後の風を読み、赤ワイン色の翼で嵐の中を舞う飛竜。二つの頭はいつも息がぴったり。","片方が眠っても、もう片方が見張っている。"],"cobalt_silver_threehead_jademace_hydra":["三つの頭と翡翠色の尾槌を持つ海の竜。尾槌で海底をたたき、潮の流れを変える。","三つの頭で、魚の取り合いをする。"],"burgundy_ivory_fourclaw_spikewheel_ouroboros_dragon":["自分のしっぽをくわえて輪になり、棘で古い宝を守る竜。輪の中は時間がゆっくり流れる。","輪をほどくのは、千年に一度だけ。"],"ivory_jade_sixwing_serpentine_amphiptere":["六枚の翼で雲の上を渡る白い天の蛇。羽ばたくたびに虹のかけらが舞う。","雲の上で、いつも日なたぼっこをしている。"],"brass_emerald_bladejaw_fourfin_dunkleodragon":["鎧のような鱗と鋼の顎を持つ古代の海竜。太古の海の底で、今も獲物を待ち続ける。","顎の力は、船の錨も噛みくだく。"],"obsidian_gold_foureye_hoodcrest_cobra_wyrm":["四つの眼と金の冠飾りを持つ蛇竜。冠を広げると、砂漠の熱気がぴたりと止まる。","にらまれた砂嵐は、くるりと向きを変える。"],"black_prism_six_mask_sovereign":["六つの仮面にそれぞれ違う記憶を宿す黒晶の王。仮面をつけかえるたびに声も性格も変わる。","本当の顔を知る者は、まだいない。"],"crimson_mirror_sixarm_judge":["六本の腕と赤い鏡で、言葉の真意を映し出す審判者。うその言葉は鏡の中で黒く濁る。","この鏡の前では、正直がいちばん。"],"ivory_labyrinth_sovereign":["迷路模様の甲羅に、忘れられた道をすべて刻んだ覇王。迷子は甲羅をたどれば家に帰れる。","甲羅の迷路は、作った本人も時々迷う。"],"amber_lantern_sixleg_qilin":["六本の脚で世界を旅し、灯籠の光で夜道を照らす麒麟。光の届く場所では争いが起きない。","ことのは島の大樹に呼ばれて来たらしい。"],"volcanic_gryphon":["炎色の翼で火山の上昇気流を乗りこなすグリフォン。噴火の前には必ず空高く舞い上がる。","この鳥が騒いだら、火山に近づかないこと。"],"jade_bamboo_cathedral_titan":["竹林の聖堂を背中に背負って歩く巨神。背中の竹林では小さな精霊たちが暮らしている。","一歩ごとに、竹の葉が鈴のように鳴る。"],"ruby_club_mantis_shrimp_leviathan":["紅玉の拳で岩をも砕く深海の王。七色の殻は深海の暗闇でも光を放つ。","パンチの速さは、雷よりも速いといわれる。"],"cinnabar_kiln_titan":["朱色の窯から生まれた巨兵。体の中の炎で器を焼き、冬には村人を温める。","胸の窯の火は、一度も消えたことがない。"]};   // id: [生態, 一言]
// Registered before companion-ui.js runs, so they are full species everywhere (dex, breeding, saves).
for(const [id,name,tier] of MORE_MONSTERS)COMPANION_DATA.species[id]={name,img:'assets/monsters/'+id+'.webp',power:[0,3,4,6,8][tier],...(tier===4?{fusionOnly:true}:{})};
for(const [id,fam] of Object.entries(MONSTER_FAMILY))if(COMPANION_DATA.species[id])COMPANION_DATA.species[id].family=fam;
for(const [a,b,child] of MORE_RECIPES)COMPANION_DATA.recipes.push({parents:[a,b],child});
/* Battle enemies, encounter zones, praise likes and field-guide entries (needs ENEMIES/ZONES from the main script). */
function initMoreMonsters(){
 for(const [id,[eco,quote]] of Object.entries(MONSTER_LORE))DEX_INFO[id]={...DEX_INFO[id],eco,quote};
 for(const [id,name,tier,zone,likes,habitat,note,hp,atk] of MORE_MONSTERS){
  DEX_INFO[id]={...DEX_INFO[id],habitat,note};if(tier===4)continue;
  ENEMIES[id]={name,jp:name,companion:id,hp,atk,exp:Math.round(hp*.55),gold:Math.round(hp/3),spr:'wisp',pal:{1:'#9bd573',2:'#fff',E:'#142020'}};
  LIKES[id]={tags:likes,need:tier===1?2:tier===2?3:4,hint:note};
  if(ZONES[zone])ZONES[zone].foes.push(id)}}

for(const [id,,tier] of MORE_MONSTERS)COMPANION_DATA.species[id].rarity=1+(tier-1)*3;
for(const [id,rarity] of Object.entries({seedpod_mouse:1,lotus_root_sproutling:1,silk_leaf_caterpillar:1,pinecone_sparrow:1,sprout_ear_mole:4,lantern_moth:4,thunder_feather_owlet:7,ancient_forest_stag:10}))COMPANION_DATA.species[id].rarity=rarity;
